entries[221778] = { ["name"] = "Champion: Taoshi", ["text"] = "Sofort\nKein Schurke beherrschte die Verstohlenheit so gut wie Taoshi. Wenn sie nicht will, dass sie jemand sieht, dann gelingt das auch niemandem. Diese Fähigkeit macht sie besonders tödlich, da ihr Überraschungsangriff von hinten so gut wie unmöglich zu verhindern ist." }
