entries[221883] = { ["name"] = "Göttliches Ross", ["text"] = "Sofort\nVergeltung ( Vergeltungspaladin )\nSchwingt Euch auf Euer Streitross, das Eure Bewegungsgeschwindigkeit 3 Sek. lang um 100% erhöht. Kann im Kampf oder in Innenräumen genutzt werden.\n\nHeilig, Schutz\nSchwingt Euch auf Euer Streitross, das Eure Bewegungsgeschwindigkeit 3 Sek. lang um 100% erhöht. Kann im Kampf oder in Innenräumen genutzt werden.\n\"Vom Licht erlöst, Eurer Sache ergeben.\"\nPaladin" }
