entries[221885] = { ["name"] = "Göttliches Ross", ["text"] = "Sofort\nVergeltung ( Vergeltungspaladin )\nSchwingt Euch auf Euer Streitross, das Eure Bewegungsgeschwindigkeit 3 Sek. lang um 100% erhöht. Kann im Kampf oder in Innenräumen genutzt werden.\n\nHeilig, Schutz\nSchwingt Euch auf Euer Streitross, das Eure Bewegungsgeschwindigkeit 3 Sek. lang um 100% erhöht. Kann im Kampf oder in Innenräumen genutzt werden.\n\"Zum Tagesanbruch führen die edlen Sonnenläufer häufig Rituale aus, um ihre Reittiere zu segnen und sie mit heiliger Magie zu erfüllen.\"\nPaladin" }
entries[221886] = { ["name"] = "Göttliches Ross", ["text"] = "Sofort\nVergeltung ( Vergeltungspaladin )\nSchwingt Euch auf Euer Streitross, das Eure Bewegungsgeschwindigkeit 3 Sek. lang um 100% erhöht. Kann im Kampf oder in Innenräumen genutzt werden.\n\nHeilig, Schutz\nSchwingt Euch auf Euer Streitross, das Eure Bewegungsgeschwindigkeit 3 Sek. lang um 100% erhöht. Kann im Kampf oder in Innenräumen genutzt werden.\n\"Ein treuer Begleiter für jeden, der Silbermond beschützt.\"\nPaladin" }
entries[221887] = { ["name"] = "Göttliches Ross", ["text"] = "Sofort\nVergeltung ( Vergeltungspaladin )\nSchwingt Euch auf Euer Streitross, das Eure Bewegungsgeschwindigkeit 3 Sek. lang um 100% erhöht. Kann im Kampf oder in Innenräumen genutzt werden.\n\nHeilig, Schutz\nSchwingt Euch auf Euer Streitross, das Eure Bewegungsgeschwindigkeit 3 Sek. lang um 100% erhöht. Kann im Kampf oder in Innenräumen genutzt werden.\n\"Die Ehre, diesen Elekk zu reiten, wird nur den herausragendsten Paladinen gewährt. Seine Plattenrüstung und sein lila Schmuck wurden von Prophet Velen persönlich gesegnet.\"\nQuest" }
